import mongoose from 'mongoose';

// Coaching report for one student. Either written offline (scripts/analysis-*.js, admin upload) or
// generated by Claude on request (server/lib/coachAI.js), for all their tests or for one paper.
const reportSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },
    scope: { type: String, enum: ['overall', 'attempt'], default: 'overall' },
    attempt: { type: mongoose.Schema.Types.ObjectId, ref: 'Attempt', default: null }, // set when scope = 'attempt'
    source: { type: String, enum: ['offline', 'ai'], default: 'offline' },
    // AI reports are created 'pending' and filled in by a background job.
    status: { type: String, enum: ['pending', 'ready', 'failed'], default: 'ready' },
    error: String,
    title: { type: String, required: true },
    summary: String, // supports $LaTeX$ and **bold**, like questions
    basedOn: { attempts: Number, questions: Number, through: Date },
    weakTopics: [{ _id: false, subject: String, topic: String, severity: { type: String, enum: ['high', 'medium', 'low'] }, evidence: String, advice: String }],
    strengths: [{ _id: false, subject: String, topic: String, note: String }],
    habits: [{ _id: false, title: String, detail: String }], // time management, skipping, guessing…
    plan: [{ _id: false, step: String, task: String }],
    author: String,
    model: String,
    usage: { inputTokens: Number, outputTokens: Number, cacheReadTokens: Number },
  },
  { timestamps: true }
);
reportSchema.index({ user: 1, scope: 1, attempt: 1, createdAt: -1 });

export default mongoose.models.AnalysisReport || mongoose.model('AnalysisReport', reportSchema);
